mapper.select:
SELECT 


 ORDER BY ${sortColumn} ${sortDirection}, o.order_seq DESC
 LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE tb_order
   SET order_status = #{toStatus},
       updated_by   = #{updatedBy},
       updated_at   = CURRENT_TIMESTAMP
 WHERE order_seq    = #{orderSeq}
   AND order_status = #{fromStatus}

UPDATE tb_order_line
   SET line_status = #{toStatus},
       updated_by  = #{updatedBy},
       updated_at  = CURRENT_TIMESTAMP
 WHERE order_seq   = #{orderSeq}
   AND line_status = #{fromStatus}

mapper.select:
SELECT m.sku_seq
  FROM tb_channel_sku m
 WHERE m.channel_seq      = #{channelSeq}
   AND m.ext_product_code = #{extProductCode}
   AND m.ext_option_code IS NOT DISTINCT FROM #{extOptionCode}
   AND m.mapping_status   = 'MAPPED'
   AND m.use_yn           = 'Y'
 LIMIT 1
